INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('5837a1d8-3e8a-58b8-912f-708e712fd761'::uuid, 'de2e1050-a0be-578b-9a3b-70eb844f7a46'::uuid, 'Électricien — offre clé en main', 'Mission de professionnels BTP portée par société d''électricité bâtiment Casablanca Maroc, basé à Casablanca. Step into the ultimate playground for click enthusiasts. ClickTopia offers a fun and engaging environment to freely test, practice, and master your mouse clicking speed. La mission couvre typiquement les volets réalisation / accompagnement : Conseil et cadrage de la mission, Prestation adaptée au périmètre convenu, Expertise Électricien, Suivi jusqu''à livraison de la mission. société d''électricité bâtiment Casablanca Maroc intervient à Casablanca, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation électricien, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Construction Gros Oeuvre', 'http://electricitemaroc.com/logo.svg', '["http://electricitemaroc.com/appstore.svg", "http://electricitemaroc.com/googleplay.svg", "http://electricitemaroc.com/logo.svg"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Électricien", "Suivi jusqu''à livraison de la mission"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Casablanca"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.2.1' LIMIT 1));
