INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a87c94d3-4396-54f0-8279-88c6623833ed'::uuid, 'ffb5fa3c-0501-5edd-a0d1-e41268760a9b'::uuid, 'Villa MB', 'Cette villa contemporaine conçue par Faydi Architecture illustre notre approche minimaliste et raffinée de l’architecture résidentielle haut de gamme.', '["https://lechantier.ma/uploads/media/e0fcb9c58cd9.webp", "https://lechantier.ma/uploads/media/a3d7fc8b69dd.webp", "https://lechantier.ma/uploads/media/f49dbf1d6ec7.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/e0fcb9c58cd9.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ce6dbecb-bd35-578b-8a8b-28d300a1ed8d'::uuid, 'ffb5fa3c-0501-5edd-a0d1-e41268760a9b'::uuid, 'Pharmacie', 'Ce projet consistait à concevoir et réaliser un espace pharmaceutique alliant fonctionnalité, esthétique et confort d’accueil. L’objectif était de créer une atmosphère rassurante et contemporaine, tout en respectant les normes de circulation, d’accessibilité et de visibilité des produits.', '["https://lechantier.ma/uploads/media/f1bddeea3615.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/f1bddeea3615.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
