INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('65d14079-5093-55d0-b04c-ab5f499ae1ed'::uuid, 'f9ad9b26-a96e-5503-8f66-549e10badfa7'::uuid, 'BEAULIEU ZENATA', 'Un projet de vie, dont le concept phare est le rapprochement de la forme architecturale à l''imaginaire de la courbe et des lieux de vie Zen. Du paysage jusqu''à l''aménagement extérieur, l''architecture porte un message de confort et d''havre de vie', '["https://lechantier.ma/uploads/media/cb20df55dd97.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cb20df55dd97.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
