INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1d6f9fa1-cd1a-57cf-acf1-356f94430883'::uuid, '3ded8ab8-ae97-50e6-84b9-7f7119ffb2df'::uuid, 'École primaire-Éveil et Savoir à Tanger', 'École primaire avec préscolaire située à Tanger, offrant un cadre d’apprentissage stimulant, sécurisé et adapté aux enfants. Espaces lumineux, salles pédagogiques modernes, cour de récréation et approche éducative centrée sur le développement global de l’enfant.', '["https://lechantier.ma/uploads/media/5f2329d8651d.webp", "https://lechantier.ma/uploads/media/fa4757e9f082.webp", "https://lechantier.ma/uploads/media/cf788fef1c15.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/5f2329d8651d.webp', 'Tétouan', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2f3a35fe-365a-52f1-b363-d210fd33e779'::uuid, '3ded8ab8-ae97-50e6-84b9-7f7119ffb2df'::uuid, 'Intérieurs – Appartement à Fnideq', 'Aménagement intérieur d’un appartement à Fnideq, combinant style moderne et fonctionnalité. Espaces optimisés, finitions soignées, palette de couleurs douces et mobilier élégant créent une atmosphère confortable et raffinée, adaptée à la vie urbaine.', '["https://lechantier.ma/uploads/media/7e38e9df1d88.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/7e38e9df1d88.webp', 'Tétouan', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6582fb07-76e4-5dcd-b30f-77190f42420d'::uuid, '3ded8ab8-ae97-50e6-84b9-7f7119ffb2df'::uuid, 'Réalisation — ANAS ABARA ARCHITECTURE', NULL, '["https://lechantier.ma/uploads/media/fa4757e9f082.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/fa4757e9f082.webp', 'Tétouan', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('75f49a18-b755-5080-9dd0-4a07c93cda88'::uuid, '3ded8ab8-ae97-50e6-84b9-7f7119ffb2df'::uuid, 'Réalisation — ANAS ABARA ARCHITECTURE', NULL, '["https://lechantier.ma/uploads/media/cf788fef1c15.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cf788fef1c15.webp', 'Tétouan', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b2588477-804f-547e-a391-d07ddaec2d66'::uuid, 'c7bece4e-ec69-56fb-a127-d927aa9e6efe'::uuid, 'immeuble Tassila', 'Immeuble résidentiel R+3 situé à Marrakech, alliant architecture contemporaine et touches marocaines. Façade en tons ocres, claustras décoratifs, balcons ombragés. Appartements lumineux avec terrasses. Conception bioclimatique, matériaux durables, cadre de vie confortable et intégré au climat local.', '["https://lechantier.ma/uploads/media/ba112a826b69.webp", "https://lechantier.ma/uploads/media/51ec02c19a5f.webp", "https://lechantier.ma/uploads/media/866804ccdf01.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ba112a826b69.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a58040e8-38ab-5c87-819b-5333544a4ddc'::uuid, 'c7bece4e-ec69-56fb-a127-d927aa9e6efe'::uuid, 'Imm Karnac', 'Immeuble résidentiel R+3 à Marrakech, mêlant design moderne et inspirations locales. Façade élégante aux tons naturels, balcons ombragés et finitions traditionnelles. Appartements spacieux et lumineux avec espaces extérieurs. Conception durable adaptée au climat pour un confort optimal.', '["https://lechantier.ma/uploads/media/4784ca12f6d7.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/4784ca12f6d7.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('af719fa6-9986-5824-8d97-478e620a7ad4'::uuid, 'c7bece4e-ec69-56fb-a127-d927aa9e6efe'::uuid, 'Réalisation — AWA ARCHITECTS', NULL, '["https://lechantier.ma/uploads/media/51ec02c19a5f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/51ec02c19a5f.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('61d76c20-2d90-578d-8f83-7af34a60d682'::uuid, 'c7bece4e-ec69-56fb-a127-d927aa9e6efe'::uuid, 'Réalisation — AWA ARCHITECTS', NULL, '["https://lechantier.ma/uploads/media/866804ccdf01.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/866804ccdf01.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6e956e1f-4bf2-5150-a6d2-fc575af4bd3f'::uuid, 'eab790b9-d91a-5a5b-94df-2a848386b835'::uuid, 'Cabinet de dermatologie à Nador', 'Conception d’un cabinet de dermatologie à Nador : un espace clair et fluide, structuré par des courbes douces et des plafonds élégants. Lumière maîtrisée, palette taupe et blanc, béton ciré et alcôves intimes composent un lieu apaisant, fonctionnel et pensé pour soigner.', '["https://lechantier.ma/uploads/media/cb387ea2d0d5.webp", "https://lechantier.ma/uploads/media/c01ad5e29deb.webp", "https://lechantier.ma/uploads/media/90249b7a4851.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cb387ea2d0d5.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('1e1b3c89-2729-5141-97aa-c627fb437f81'::uuid, 'eab790b9-d91a-5a5b-94df-2a848386b835'::uuid, 'Concours - Terminal Aéroport de tanger', 'Fruit d''une collaboration avec Mao Architecture, Atelier AZ et Modak4art dans le cadre de la proposition d''une conception visionnaire pour le projet du nouveau terminal de l''aéroport de Tanger. Notre concept architectural, inspiré par les caractéristiques géologiques et maritimes de Tanger. lire plus sur notre site\*', '["https://lechantier.ma/uploads/media/d9a24ec003ad.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/d9a24ec003ad.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
