INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('ed76c263-baaf-5108-9c6b-51a346224f37'::uuid, '0c2cc11c-e3fb-529b-b020-9c5f65bff8db'::uuid, 'Réalisation — Archi groupe', NULL, '["https://lechantier.ma/uploads/media/8551b7f5e5a9.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/8551b7f5e5a9.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d5644666-7934-59b3-82f0-304d56cd8128'::uuid, 'c881d153-cfdf-53eb-adc8-de340ae040d6'::uuid, 'Construction d’une villa contemporaine à Casablanca', 'Une composition contemporaine basée sur des volumes purs et superposés, jouant sur les porte-à-faux, la transparence et l’ouverture vers l’extérieur. Les lignes épurées, les grandes baies vitrées et l’intégration paysagère créent une architecture élégante, lumineuse et en harmonie avec son environnement.', '["https://lechantier.ma/uploads/media/ad50b73df6c8.webp", "https://lechantier.ma/uploads/media/fce548f925d1.webp", "https://lechantier.ma/uploads/media/aff9cd5dcbe1.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ad50b73df6c8.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('eee1a852-6295-5a1b-b552-2244834c95bc'::uuid, 'c881d153-cfdf-53eb-adc8-de340ae040d6'::uuid, 'Collège Aloula à Marrakech', 'Le projet adopte une écriture architecturale contemporaine et sobre, fondée sur des volumes clairs, une façade rythmée et une intégration maîtrisée dans le tissu urbain. L’architecture privilégie la lisibilité, la fonctionnalité et le confort, tout en affirmant une identité institutionnelle moderne', '["https://lechantier.ma/uploads/media/8c9d5314e560.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/8c9d5314e560.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('525848e9-55a8-56b1-b48d-a19b11ba0e1f'::uuid, 'c881d153-cfdf-53eb-adc8-de340ae040d6'::uuid, 'Réalisation — Mimar slim', NULL, '["https://lechantier.ma/uploads/media/fce548f925d1.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/fce548f925d1.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6c80bd61-d2d2-5681-bcaf-c97bdd05f665'::uuid, 'c881d153-cfdf-53eb-adc8-de340ae040d6'::uuid, 'Réalisation — Mimar slim', NULL, '["https://lechantier.ma/uploads/media/aff9cd5dcbe1.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/aff9cd5dcbe1.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b1ba83bc-6566-5b12-9435-80293550ecb4'::uuid, '69c7167b-5afd-5f1d-a306-db768d854306'::uuid, 'House I', 'Villa Art Déco en construction à L’Oasis, Casablanca. Une architecture élégante aux lignes épurées, baignée de lumière naturelle, au cœur d’un jardin tropical soigneusement aménagé. Ce projet harmonise modernité, héritage et confort pour offrir un cadre de vie raffiné, intemporel et ouvert sur l’extérieur.', '["https://lechantier.ma/uploads/media/bb9298ef5b61.webp", "https://lechantier.ma/uploads/media/7cbb262d9fee.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/bb9298ef5b61.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a018dc5d-d52f-5066-ac28-c88821ff0b19'::uuid, '69c7167b-5afd-5f1d-a306-db768d854306'::uuid, 'Lobby Hotel by Hilton', 'Un design contemporain et chaleureux, mêlant lignes épurées, textures raffinées et teintes naturelles. L’espace accueille les visiteurs dans une ambiance élégante et confortable, avec un mobilier sur mesure, des luminaires graphiques et une atmosphère propice à la détente et à l’échange. Ce projet est en chantier', '["https://lechantier.ma/uploads/media/3c373bf371f8.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3c373bf371f8.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
