INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('cb96e3a6-1117-5966-af4f-4af61df4724b'::uuid, 'ffc9120b-780f-51df-ab37-f972bc5f9e92'::uuid, 'Réalisation — HAM-ARCHI', NULL, '["https://lechantier.ma/uploads/media/c7d1e45a6453.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c7d1e45a6453.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('64b829a4-5163-5ace-8a0a-ae4b93d82539'::uuid, 'f776cf86-84c1-5450-a961-3d70e519ff09'::uuid, 'VILLA M', 'Villa M est un projet qui fait une déclaration dans son emplacement à Targa, Marrakech. C’est un projet privé orienté vers la famille. Nous avons conçu cet espace pour une famille de cinq personnes afin de les rassembler et leur offrir une multitude d’espaces et d’expériences à apprécier à travers la transparence tout en apportant l’intimité', '["https://lechantier.ma/uploads/media/8ef0d73382d2.webp", "https://lechantier.ma/uploads/media/209a8f11d818.webp", "https://lechantier.ma/uploads/media/11a0657b6419.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/8ef0d73382d2.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('afe94603-0b88-5521-962d-ffe6ec671891'::uuid, 'f776cf86-84c1-5450-a961-3d70e519ff09'::uuid, 'TOUR D’IVOIRE', 'Situé dans le quartier moderne de Guéliz dans la ville de Marrakech, « IVORY TOWER » est un projet qui répond de manière chirurgicale aux contraintes du site, entre une avenue sur une façade et une ruelle sur l’autre. Pour ce bâtiment de six étages orienté en studios, nous avons choisi de créer une occultation sur la façade protégeant l’intimité.', '["https://lechantier.ma/uploads/media/f638fbde5a83.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/f638fbde5a83.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9e1fc30d-3dae-5c81-b77e-f604aba1525f'::uuid, 'f776cf86-84c1-5450-a961-3d70e519ff09'::uuid, 'Réalisation — AL ARCHITECTS & PARTNERS', NULL, '["https://lechantier.ma/uploads/media/209a8f11d818.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/209a8f11d818.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('da9b8662-a022-5f3e-8130-35aa0251880c'::uuid, 'f776cf86-84c1-5450-a961-3d70e519ff09'::uuid, 'Réalisation — AL ARCHITECTS & PARTNERS', NULL, '["https://lechantier.ma/uploads/media/11a0657b6419.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/11a0657b6419.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4963704b-4cfc-5e53-b8e6-70244de82110'::uuid, 'ac11bcba-4c81-56d3-991a-08c31b3f78b0'::uuid, 'Maison des jeunes', 'La maison de jeunes de Sidi Bouathmane se distingue par une architecture contemporaine, pensée pour encourager la créativité, la participation et le développement personnel des jeunes. Les espaces, à la fois ouverts, modulables et baignés de lumière naturelle, offrent une grande diversité d’usages pour des jeunes en plein développement', '["https://lechantier.ma/uploads/media/6646c9e5e0c9.webp", "https://lechantier.ma/uploads/media/e1ddd4555b52.webp", "https://lechantier.ma/uploads/media/39b69264d3fb.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/6646c9e5e0c9.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9934e295-811a-5cce-b9e5-6c3f0d81261d'::uuid, 'ac11bcba-4c81-56d3-991a-08c31b3f78b0'::uuid, 'Internat Sidi Mokhtar', 'Ce projet, s’inscrit dans une volonté régionale de renforcer l’accès à l’éducation en milieu rural, dans la commune de Sidi Mokhtar. Implanté à proximité d’un collège existant, l’internat a été conçu par notre agence d’architecture à Marrakech comme un lieu de vie équilibré, structuré et inclusif, capable d’accueillir un grand nombre d’élèves', '["https://lechantier.ma/uploads/media/0d09ad7b9006.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/0d09ad7b9006.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('39c375a4-0697-572b-b526-12260bf1beb6'::uuid, 'ac11bcba-4c81-56d3-991a-08c31b3f78b0'::uuid, 'Réalisation — HBA STUDIO', NULL, '["https://lechantier.ma/uploads/media/e1ddd4555b52.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/e1ddd4555b52.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('69db8997-f164-5182-a66f-9c22063bee00'::uuid, 'ac11bcba-4c81-56d3-991a-08c31b3f78b0'::uuid, 'Réalisation — HBA STUDIO', NULL, '["https://lechantier.ma/uploads/media/39b69264d3fb.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/39b69264d3fb.webp', 'Marrakech', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('7203362e-5b79-567b-a5cb-4f809eaf31be'::uuid, '37602adf-d427-5094-8694-e745d838ece5'::uuid, 'Habillage mural en miroir', 'Création murale sur mesure alliant bois, miroir et éclairage LED pour un effet sculptural et moderne. Castlewood sublime vos espaces avec des habillages muraux élégants, fonctionnels et conçus avec précision.', '["https://lechantier.ma/uploads/media/cc50be831f22.webp", "https://lechantier.ma/uploads/media/c662b9a6b33b.webp", "https://lechantier.ma/uploads/media/3db77e3b4123.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/cc50be831f22.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9f47605c-2a66-570c-8d1b-030e15e9efff'::uuid, '37602adf-d427-5094-8694-e745d838ece5'::uuid, 'Aménagement d’un Cabinet d’Avocat', 'Conception et réalisation complète de l’espace de travail d’un avocat dans un style moderne et chaleureux. Le projet intègre une optimisation fonctionnelle de l’espace tout en respectant l’élégance requise pour un cabinet juridique.', '["https://lechantier.ma/uploads/media/52a4a629e160.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/52a4a629e160.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('194d4b35-4b17-589c-b82e-cf31a97d944f'::uuid, '37602adf-d427-5094-8694-e745d838ece5'::uuid, 'Réalisation — Castlewood', NULL, '["https://lechantier.ma/uploads/media/c662b9a6b33b.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c662b9a6b33b.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.1' LIMIT 1));
