INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f5188dc2-6c69-54d0-95cd-8f508ef2eb89'::uuid, '39ddd7cc-e17f-5b5e-8be0-6dab1c843146'::uuid, 'Réalisation — RZAL EL MILOUDI', NULL, '["https://lechantier.ma/uploads/media/be30e60af4a2.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/be30e60af4a2.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('e6f52329-7958-5958-a45e-521e831d9243'::uuid, 'ed6e5a9f-4800-5ce2-b42a-86339db6b45a'::uuid, 'Amenadement', 'ste: dfye(DecoForYouElite) a réalisé l’aménagement complet d’un appartement initialement de standing moyen, transformé en haut standing grâce à une transformation haut de gamme en aluminium et verre', '["https://lechantier.ma/uploads/media/58aeb6716378.webp", "https://lechantier.ma/uploads/media/1d52f9d62f91.webp", "https://lechantier.ma/uploads/media/5ab0461be5a3.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/58aeb6716378.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
